/**
 * The Worker configs of a stack's backend: its Ledger, its public calendar feed Worker, and its public Gallery Worker.
 *
 * A stack is the shared one (every site without `tenants/<id>/deployment.json`) or a site's own. Each Worker gets a
 * folder in `.generated/`: `shared/<worker>/` or `sites/<id>/<worker>/`, holding `wrangler.jsonc` (paths relative to
 * the folder, as wrangler resolves them) and, for the two that have one, the entry file that re-exports the
 * platform package. The files are gitignored and deterministic, regenerated by `hearthlog build` and the deploy tools.
 */

import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join, relative } from "node:path";

import { GENERATED_DIRECTORY } from "../compose/compose-modules.js";
import { packageDirectory } from "../host/write-host.js";
import { buildCalendarPublicConfig } from "../public-workers/calendar-public-config.js";
import { buildGalleryPublicConfig } from "../public-workers/gallery-public-config.js";
import { buildLedgerConfig } from "./ledger-config.js";
import { infrastructureFor, loadTenantConfig, type InfrastructureDefinition } from "./tenant-config.js";

export type HostWorker = "ledger" | "calendar-public" | "gallery-public";
/** "shared" or a site id. */
export type Stack = string;

export function hostWorkerDirectory(stack: Stack, worker: HostWorker): string {
    return stack === "shared"
        ? join(GENERATED_DIRECTORY, "shared", worker)
        : join(GENERATED_DIRECTORY, "sites", stack, worker);
}

export function hostWorkerConfigPath(stack: Stack, worker: HostWorker): string {
    return join(hostWorkerDirectory(stack, worker), "wrangler.jsonc");
}

const LEDGER_ENTRY = `// The Ledger Worker's entry. The code is \`@hearthlog/ledger\`; the Durable Object classes keep these
// exact names because deployed data is tied to them.
export { AppRegistry, LedgerApp, default } from "@hearthlog/ledger/index.js";
`;

const CALENDAR_ENTRY = `// The public calendar feed Worker's entry; the code is \`@hearthlog/cloudflare\`.
export { default, handleCalendarPublicRequest, type CalendarPublicEnv } from "@hearthlog/cloudflare/calendar-public.js";
`;

function calendarTsconfig(directory: string): string {
    const types = join(packageDirectory("@hearthlog/cloudflare"), "types", "worker-configuration.d.ts");
    return `${JSON.stringify({
        compilerOptions: {
            target: "ES2022", module: "ESNext", moduleResolution: "Bundler", lib: ["ES2022", "DOM"],
            strict: true, noEmit: true, skipLibCheck: true, types: [],
        },
        include: ["index.ts", relative(directory, types)],
    }, null, 2)}\n`;
}

async function write(path: string, content: string): Promise<void> {
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, content, "utf8");
}

const json = (value: unknown) => `${JSON.stringify(value, null, 2)}\n`;

/**
 * Write the configs of one stack. A build passes its own site's stack ("shared" for a site on the shared stack),
 * because its catalog holds only its own modules; `check:tenants` passes each stack in turn.
 */
export async function generateHostConfigs(stack: Stack): Promise<string[]> {
    const { infrastructure: shared, sites, stacks } = await loadTenantConfig(undefined, { only: stack === "shared" ? "" : stack });
    const written: string[] = [];
    const emit = async (worker: HostWorker, config: unknown, files: Record<string, string> = {}) => {
        const directory = hostWorkerDirectory(stack, worker);
        await write(join(directory, "wrangler.jsonc"), json(config));
        written.push(join(directory, "wrangler.jsonc"));
        for (const [name, content] of Object.entries(files)) await write(join(directory, name), content);
    };
    let infrastructure: InfrastructureDefinition = shared;
    let ledgerAccount: string | undefined;
    let calendarSites = stacks.filter((entry) => entry.shared).map((entry) => entry.id);
    let gallery = true;
    if (stack !== "shared") {
        const site = sites.find((candidate) => candidate.id === stack);
        if (!site?.deployment) throw new Error(`Site "${stack}" has no tenants/${stack}/deployment.json, so it has no stack of its own`);
        infrastructure = infrastructureFor(site, shared);
        ledgerAccount = site.deployment.accountId;
        calendarSites = [site.id];
        gallery = (site.features as readonly string[]).includes("gallery");
    } else if (calendarSites.length === 0) {
        return written;
    }
    await emit("ledger", buildLedgerConfig(infrastructure, ledgerAccount), { "index.ts": LEDGER_ENTRY });
    const calendarDirectory = hostWorkerDirectory(stack, "calendar-public");
    await emit("calendar-public", buildCalendarPublicConfig(infrastructure, calendarSites), {
        "index.ts": CALENDAR_ENTRY,
        "tsconfig.json": calendarTsconfig(calendarDirectory),
    });
    if (gallery) await emit("gallery-public", buildGalleryPublicConfig(infrastructure));
    return written;
}
